        ]),
        ChangelogDay(date: "2026-10-23", entries: [
            .new("2026-10-23-own-eggs") { $0.t("보증마다 고유한 알: 고급·희귀 이상은 보석, 타입마다 하나, 타입:널의 알까지.",
